struct ListNode{int val;ListNode*next;ListNode(int x):val(x),next(0){}}; class Solution{public:ListNode* sortList(ListNode*h){if(!h||!h->next)return h;ListNode*a=h,*b=h->next;while(b&&b->next)a=a->next,b=b->next->next;ListNode*r=a->next;a->next=0;h=sortList(h);r=sortList(r);ListNode d(0),*p=&d;while(h&&r){if(h->val<r->val)p->next=h,h=h->next;else p->next=r,r=r->next;p=p->next;}p->next=h?h:r;return d.next;}};
